import re

def find_middle(input_str):
    if not isinstance(input_str, str):
        return -1

    digits = re.findall(r'\d', input_str)
    if not digits:
        return -1

    product = 1
    for digit in digits:
        product *= int(digit)

    product_str = str(product)
    if len(product_str) == 1:
        return int(product_str)

    if len(product_str) % 2 == 1:
        middle_index = len(product_str) // 2
        return int(product_str[middle_index])
    else:
        middle_index = len(product_str) // 2
        result = product_str[middle_index - 1:middle_index + 1]
        if result[0] == '0':
            return int(result[1])
        else:
            return int(result)

# Example usage:
# print(find_middle('s7d8jd9'))  # Output: 0
# print(find_middle('1563'))     # Output: 56
# print(find_middle('2016'))     # Output: 1
